button.content:
@switch (variant()) {
  @case ('crud') {
    <div class="d-flex align-items-center flex-wrap gap-8">
      <sd-button title="Tạo liên hệ" type="fill" color="primary" routerLink="/pattern/drawer/create" /><sd-button
        title="Lưu thay đổi"
        type="outline"
        routerLink="/pattern/drawer/update" /><sd-button title="Chỉnh sửa" type="text" routerLink="/pattern/drawer/update" /><sd-button
        title="Xem chi tiết"
        type="text"
        routerLink="/pattern/drawer/detail" />
    </div>
    <p class="text-secondary fs-13">Mở đúng mẫu create/update/detail để thử hành động. Detail dùng Đóng; update dùng Lưu thay đổi.</p>
  }
  @case ('query') {
    <div class="d-flex align-items-center flex-wrap gap-8">
      <sd-button title="Tìm kiếm" type="fill" color="primary" routerLink="/pattern/table/filter" /><sd-button
        title="Áp dụng bộ lọc"
        type="outline"
        routerLink="/pattern/composition/listing" /><sd-button
        title="Xóa bộ lọc"
        type="text"
        (click)="message.set('Đưa các điều kiện về mặc định; thử query thật trong mẫu Listing.')" />
    </div>
  }
  @case ('workflow') {
    <div class="d-flex align-items-center flex-wrap gap-8">
      <sd-button title="Gửi duyệt" type="fill" color="primary" (click)="message.set('Đã gửi đơn hàng mẫu để chờ duyệt.')" /><sd-button
        title="Duyệt đơn hàng"
        type="outline"
        (click)="message.set('Đã duyệt đơn hàng mẫu.')" /><sd-button
        title="Từ chối"
        type="text"
        (click)="message.set('Đã từ chối đơn hàng mẫu.')" />
    </div>
    <p class="text-secondary fs-13">Tham khảo câu chữ; thao tác chuyển trạng thái bản ghi nằm ở Hàng đợi xử lý.</p>
  }
  @case ('danger') {
    @if (!deleted()) {
      <p>Đơn hàng mẫu DH-1024 · An Phát</p>
      <sd-button title="Xóa đơn hàng" color="error" type="fill" (click)="remove()" />
    } @else {
      <sd-button title="Khôi phục dữ liệu mẫu" (click)="deleted.set(false); message.set('')" />
    }
  }
  @case ('async') {
    <sd-button
      [title]="saving() ? 'Đang lưu…' : attempt() === 1 ? 'Thử lại' : 'Lưu thay đổi'"
      type="fill"
      color="primary"
      [disabled]="saving()"
      [loading]="saving()"
      (click)="save()" />
    <p class="text-secondary fs-13">Lần lưu đầu mô phỏng lỗi; thử lại thành công. Không gửi lặp khi pending.</p>
  }
}
<p role="status">{{ message() }}</p>

import { ChangeDetectionStrategy, Component, DestroyRef, inject, input, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdConfirmService } from '@sdcorejs/angular/services/confirm';
@Component({
  selector: 'app-pattern-button',
  imports: [RouterLink, SdButton],
  templateUrl: './button.component.html',
  styleUrl: '../../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ButtonComponent {
  readonly variant = input('crud');
  readonly message = signal('');
  readonly saving = signal(false);
  readonly attempt = signal(0);
  readonly deleted = signal(false);
  private readonly confirm = inject(SdConfirmService);
  private readonly destroy = inject(DestroyRef);
  async remove(): Promise<void> {
    try {
      await this.confirm.confirm('Đơn hàng DH-1024 sẽ bị xóa khỏi danh sách mẫu này.', {
        title: 'Xóa đơn hàng DH-1024?',
        yesTitle: 'Xóa đơn hàng',
        noTitle: 'Giữ lại',
        yesButtonColor: 'error',
      });
      this.deleted.set(true);
      this.message.set('Đã xóa đơn hàng mẫu DH-1024.');
    } catch {
      this.message.set('Đã giữ lại đơn hàng.');
    }
  }
  async save(): Promise<void> {
    if (this.saving()) return;
    this.saving.set(true);
    this.message.set('');
    await new Promise(r => setTimeout(r, 500));
    if (this.destroy.destroyed) return;
    this.attempt.update(x => x + 1);
    this.saving.set(false);
    this.message.set(this.attempt() === 1 ? 'Không thể lưu. Dữ liệu được giữ nguyên; vui lòng thử lại.' : 'Đã lưu thay đổi.');
  }
}

:host {
