import { ChangeDetectionStrategy, Component, DestroyRef, OnInit, computed, inject, input, output, signal } from '@angular/core';
import { FormArray, FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdInput } from '@sdcorejs/angular/forms/input';
import { SdSelect } from '@sdcorejs/angular/forms/select';
import { SdTextarea } from '@sdcorejs/angular/forms/textarea';
import { PatternDraft } from '../data/pattern-draft';
import { SdNotifyService } from '@sdcorejs/angular/services/notify';
import { REGIONS } from '../data/pattern-query';
import { merge } from 'rxjs';
export interface ContactRecord {
  name: string;
  email: string;
  phone: string;
  region: string;
  note: string;
}
export const emptyContact = (): ContactRecord => ({ name: '', email: '', phone: '', region: REGIONS[0], note: '' });
export const sampleContact = (): ContactRecord => ({
  name: 'Nguyễn Minh Anh',
  email: 'minhanh@example.test',
  phone: '0900000000',
  region: REGIONS[0],
  note: 'Đầu mối phối hợp',
});
@Component({
  selector: 'app-pattern-form-editor',
  imports: [ReactiveFormsModule, SdButton, SdInput, SdSelect, SdTextarea],
  templateUrl: './form-editor.component.html',
  styleUrl: '../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FormEditorComponent implements OnInit {
  readonly layout = input('simple');
  readonly mode = input('create');
  readonly initial = input<ContactRecord>(emptyContact());
  readonly hideFooter = input(false);
  readonly saved = output<ContactRecord>();
  readonly cancelled = output<void>();
  readonly saving = signal(false);
  readonly message = signal('');
  readonly attempted = signal(false);
  readonly fail = signal(false);
  readonly revision = signal(0);
  private baseline = '';
  // Core fields register and validate their own controls on this group.
  readonly form = new FormGroup<Record<string, FormControl>>({});
  readonly orderName = new FormControl('', { nonNullable: true, validators: [Validators.required] });
  readonly lines = new FormArray<FormGroup<{ name: FormControl<string>; quantity: FormControl<number>; price: FormControl<number> }>>([]);
  readonly regions = REGIONS.map(name => ({ id: name, name }));
  readonly total = computed(() => {
    this.revision();
    return this.lines.getRawValue().reduce((sum, row) => sum + Number(row.quantity) * Number(row.price), 0);
  });
  readonly dirty = computed(() => {
    this.revision();
    return this.snapshot() !== this.baseline;
  });
  private readonly draft = inject(PatternDraft);
  private readonly notify = inject(SdNotifyService);
  private readonly destroy = inject(DestroyRef);
  ngOnInit(): void {
    if (this.layout() === 'lines') this.addLine();
    this.baseline = this.snapshot();
    this.revision.update(n => n + 1);
    const subscription = merge(this.form.valueChanges, this.lines.valueChanges, this.orderName.valueChanges).subscribe(() =>
      this.revision.update(n => n + 1)
    );
    const dirty = () => this.dirty(),
      saving = () => this.saving();
    this.draft.dirty = dirty;
    this.draft.saving = saving;
    this.destroy.onDestroy(() => {
      subscription.unsubscribe();
      if (this.draft.dirty === dirty) {
        this.draft.dirty = () => false;
        this.draft.saving = () => false;
      }
    });
  }
  private snapshot(): string {
    return JSON.stringify({ contact: this.readContact(), orderName: this.orderName.value, lines: this.lines.getRawValue() });
  }
  private readContact(): ContactRecord {
    const value = this.form.getRawValue();
    const initial = this.initial();
    const field = (key: keyof ContactRecord): string => (key in value ? (value[key] ?? '') : initial[key]);
    // Stable order/defaults also cover layouts that do not render every field.
    return {
      name: field('name'),
      email: field('email'),
      phone: field('phone'),
      region: field('region'),
      note: field('note'),
    };
  }
  addLine(): void {
    if (this.saving()) return;
    this.lines.push(
      new FormGroup({
        name: new FormControl('', { nonNullable: true, validators: [Validators.required] }),
        quantity: new FormControl(1, {
          nonNullable: true,
          validators: [Validators.required, Validators.min(1), Validators.pattern(/^\d+$/)],
        }),
        price: new FormControl(0, { nonNullable: true, validators: [Validators.required, Validators.min(0)] }),
      })
    );
    this.revision.update(n => n + 1);
  }
  removeLine(index: number): void {
    if (!this.saving()) {
      this.lines.removeAt(index);
      this.revision.update(n => n + 1);
    }
  }
  async save(): Promise<boolean> {
    if (this.saving()) return false;
    this.message.set('');
    this.attempted.set(true);
    this.form.markAllAsTouched();
    this.orderName.markAsTouched();
    this.lines.markAllAsTouched();
    const invalid = this.layout() === 'lines' ? this.orderName.invalid || this.lines.invalid || !this.lines.length : this.form.invalid;
    if (invalid) {
      this.notify.error('Kiểm tra các trường bắt buộc, email hợp lệ và dòng hàng.');
      return false;
    }
    this.saving.set(true);
    this.message.set('');
    const fail = this.fail();
    this.form.disable();
    this.orderName.disable();
    this.lines.disable();
    await new Promise(resolve => setTimeout(resolve, 450));
    if (this.destroy.destroyed) return false;
    this.form.enable();
    this.orderName.enable();
    this.lines.enable();
    this.saving.set(false);
    if (fail) {
      this.notify.error('Không thể lưu. Nội dung đã nhập được giữ lại; hãy thử lại.');
      return false;
    }
    this.baseline = this.snapshot();
    this.revision.update(n => n + 1);
    this.message.set('Đã lưu dữ liệu mẫu trong phiên.');
    this.saved.emit(this.readContact());
    return true;
  }
  async cancel(): Promise<void> {
    if (await this.draft.canLeave()) {
      this.form.patchValue(this.initial());
      this.orderName.reset('');
      this.lines.clear();
      if (this.layout() === 'lines') this.addLine();
      this.baseline = this.snapshot();
      this.revision.update(n => n + 1);
      this.attempted.set(false);
      this.message.set('');
      this.cancelled.emit();
    }
  }
}

import { Injectable, inject } from '@angular/core';
import { SdConfirmService } from '@sdcorejs/angular/services/confirm';
@Injectable()
export class PatternDraft {
  private readonly confirm = inject(SdConfirmService);
  dirty: () => boolean = () => false;
  saving: () => boolean = () => false;
  async canLeave(): Promise<boolean> {
    if (this.saving()) return false;
    if (!this.dirty()) return true;
    try {
      await this.confirm.confirm('Bỏ thay đổi sẽ mất nội dung vừa nhập.', {
        title: 'Thông tin chưa được lưu',
        yesTitle: 'Bỏ thay đổi',
        noTitle: 'Tiếp tục chỉnh sửa',
      });
      return true;
    } catch {
      return false;
    }
  }
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

import { SdPermissionService } from '@sdcorejs/angular/modules/permission';
import { DOCUMENT } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, inject, input, signal, viewChild } from '@angular/core';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdSideDrawer } from '@sdcorejs/angular/components/side-drawer';
import { FormEditorComponent, ContactRecord, emptyContact, sampleContact } from '../../components/form-editor.component';
import { ContactFactsComponent } from '../../components/contact-facts.component';
import { PatternDraft } from '../../data/pattern-draft';
@Component({
  selector: 'app-pattern-drawer',
  imports: [SdButton, SdSideDrawer, FormEditorComponent, ContactFactsComponent],
  templateUrl: './drawer.component.html',
  styleUrl: '../../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DrawerComponent {
  private readonly permission = inject(SdPermissionService);
  readonly canEdit = () => this.permission.hasPermission('CRM_CONTACT_C_UPDATE');
  edit(): void {
    if (!this.canEdit()) return;
    this.mode.set('update');
  }
  readonly variant = input('create');
  readonly mode = signal('create');
  readonly opened = signal(false);
  readonly record = signal(sampleContact());
  readonly message = signal('');
  readonly drawer = viewChild.required(SdSideDrawer);
  readonly editor = viewChild(FormEditorComponent);
  private readonly draft = inject(PatternDraft);
  private readonly document = inject(DOCUMENT);
  private opener: HTMLElement | null = null;
  readonly title = computed(() =>
    this.mode() === 'create' ? 'Tạo liên hệ' : this.mode() === 'update' ? 'Chỉnh sửa liên hệ' : 'Chi tiết liên hệ'
  );
  readonly seed = computed(() => (this.mode() === 'create' ? emptyContact() : this.record()));
  open(): void {
    this.opener = this.document.activeElement as HTMLElement;
    this.mode.set(
      this.variant() === 'detail' ? 'detail' : this.variant() === 'update' || this.variant() === 'sections' ? 'update' : 'create'
    );
    this.opened.set(true);
    this.drawer().open();
  }
  readonly beforeClose = () => this.draft.canLeave();
  close(): void {
    void this.drawer().requestClose();
  }
  save(): void {
    void this.editor()?.save();
  }
  saved(record: ContactRecord): void {
    this.record.set(record);
    this.message.set('Đã lưu liên hệ ' + record.name + '.');
    this.drawer().forceClose();
  }
  closed(): void {
    this.opened.set(false);
    const opener = this.opener;
    requestAnimationFrame(() => {
      if (opener?.isConnected) opener.focus();
    });
  }
}

