@if (variant() === 'page') {
  <div class="header-layout">
    <nav class="header-variants" aria-label="Biến thể Page Header">
      @for (item of pageVariants; track item[0]) {
        <sd-button
          [title]="item[1]"
          [type]="pageVariant() === item[0] ? 'light' : 'text'"
          color="primary"
          [attr.aria-pressed]="pageVariant() === item[0]"
          (click)="pageVariant.set(item[0])" />
      }
    </nav>
    <div class="d-grid gap-20">
      @for (example of visibleExamples(); track example.id) {
        <article [attr.aria-label]="'Header ' + example.label">
          <h3 class="text-secondary fs-13 font-weight-medium m-0 mb-8">{{ example.label }}</h3>
          <div class="page-frame">
            <sd-page [title]="example.title">
              <div headerLeft class="d-flex align-items-center gap-8">
                @if (example.id !== 'list') {
                  <sd-button
                    prefixIcon="arrow_back"
                    tooltip="Quay lại"
                    type="text"
                    [disabled]="pending()[example.id]"
                    (click)="example.id === 'update' ? pageVariant.set('actions') : act(example.id, 'Quay lại')" />
                }
                <div>
                  <div class="d-flex align-items-center flex-wrap gap-8">
                    <h2>
                      {{ example.title }}
                      @if (example.id === 'detail' || example.id === 'update') {
                        <span class="text-primary">#DH-1024</span>
                      }
                    </h2>
                    @if (pageVariant() === 'advanced' && example.id === 'detail') {
                      <sd-badge
                        [title]="statuses()['detail'] || 'Chờ duyệt'"
                        type="round"
                        [color]="statuses()['detail'] === 'Đã duyệt' ? 'success' : 'warning'" />
                    }
                  </div>
                  @if (example.description && pageVariant() !== 'basic') {
                    <p class="text-secondary fs-13 m-0 mt-4">{{ example.description }}</p>
                  }
                </div>
              </div>
              <div
                headerRight
                class="d-flex align-items-center flex-wrap gap-8 justify-content-end"
                [attr.aria-label]="'Hành động ' + example.label">
                @if (['actions', 'compact', 'grouped'].includes(pageVariant()) && (example.id === 'list' || example.id === 'detail')) {
                  @if (pageVariant() === 'grouped' && secondaryActions[example.id].length >= 2) {
                    <sd-button
                      prefixIcon="more_vert"
                      tooltip="Tác vụ khác"
                      type="text"
                      [matMenuTriggerFor]="actionMenu"
                      [disabled]="pending()[example.id]" />
                    <mat-menu #actionMenu="matMenu">
                      @for (action of secondaryActions[example.id]; track action.title) {
                        <button mat-menu-item [disabled]="pending()[example.id]" (click)="act(example.id, action.title)">
                          <sd-icon [name]="action.icon" [color]="action.color" />
                          <span [class]="'text-' + action.color">{{ action.title }}</span>
                        </button>
                      }
                    </mat-menu>
                  } @else {
                    @for (action of secondaryActions[example.id]; track action.title) {
                      <sd-button
                        [title]="pageVariant() === 'compact' ? undefined : action.title"
                        [tooltip]="action.title"
                        [prefixIcon]="action.icon"
                        [color]="action.color"
                        [type]="action.color === 'secondary' ? 'text' : 'light'"
                        [disabled]="pending()[example.id]"
                        (click)="act(example.id, action.title)" />
                    }
                  }
                  @if (example.id === 'list') {
                    <sd-button
                      title="Tạo mới"
                      prefixIcon="add"
                      type="fill"
                      color="primary"
                      [loading]="pending()[example.id]"
                      [disabled]="pending()[example.id]"
                      (click)="act(example.id, 'Tạo mới')" />
                  } @else if (canEdit()) {
                    <sd-button
                      title="Chỉnh sửa"
                      prefixIcon="edit"
                      type="fill"
                      color="primary"
                      [disabled]="pending()[example.id]"
                      (click)="edit('page')" />
                  }
                } @else if (example.id === 'create' || example.id === 'update') {
                  <sd-button
                    title="Lưu"
                    prefixIcon="save"
                    type="fill"
                    color="primary"
                    [loading]="pending()[example.id]"
                    [disabled]="pending()[example.id]"
                    (click)="act(example.id, 'Lưu')" />
                }
              </div>
              <div class="sample-body">
                <span class="text-secondary fs-13">{{
                  example.id === 'list' ? '24 đơn hàng · 8 đơn chờ duyệt' : 'Thông tin đơn hàng · Khách hàng · Sản phẩm'
                }}</span>
                <p role="status">{{ messages()[example.id] }}</p>
              </div>
            </sd-page>
          </div>
        </article>
      }
    </div>
  </div>
} @else if (variant() === 'side-drawer') {
  <sd-section title="Ví dụ Side Drawer">
    @for (example of drawerExamples; track example.mode) {
      <sd-section-item [label]="example.label" labelWidth="35%">
        <div class="d-flex justify-content-end">
          <sd-button [title]="example.button" [prefixIcon]="example.icon" type="light" color="primary" (click)="openDrawer(example.mode)" />
        </div>
      </sd-section-item>
    }
  </sd-section>
  @if (confirmed().length) {
    <sd-section title="Đơn hàng đã chọn">
      @for (row of confirmed(); track row.id) {
        <sd-section-item [label]="row.code">{{ row.name }}</sd-section-item>
      }
    </sd-section>
  }
  <sd-side-drawer
    [title]="drawerMode() === 'create' ? 'Tạo đơn hàng' : drawerMode() === 'detail' ? 'Chi tiết đơn hàng' : 'Cập nhật đơn hàng'"
    width="560px"
    [beforeClose]="beforeClose">
    <div sdHeaderLeft>
      <div class="d-flex align-items-center flex-wrap gap-8">
        <h3>
          {{ drawerMode() === 'create' ? 'Tạo đơn hàng' : drawerMode() === 'detail' ? 'Chi tiết đơn hàng' : 'Cập nhật đơn hàng' }}
          @if (drawerMode() !== 'create') {
            <span class="text-primary">#DH-1024</span>
          }
        </h3>
        @if (drawerMode() !== 'create') {
          <sd-badge
            [title]="statuses()['drawer'] || 'Chờ duyệt'"
            type="round"
            [color]="statuses()['drawer'] === 'Đã duyệt' ? 'success' : 'warning'" />
        }
      </div>
      @if (drawerMode() !== 'create') {
        <p class="text-secondary fs-13 m-0 mt-4">{{ record().customer }}</p>
      }
    </div>
    <div sdHeaderRight>
      @if (groupedDrawer() && drawerMode() === 'detail') {
        <sd-button
          prefixIcon="more_vert"
          tooltip="Tác vụ đơn hàng"
          type="light"
          [matMenuTriggerFor]="drawerActions"
          [disabled]="pending()['drawer']" />
        <mat-menu #drawerActions="matMenu">
          @for (action of secondaryActions.detail; track action.title) {
            <button mat-menu-item [disabled]="pending()['drawer']" (click)="act('drawer', action.title)">
              <sd-icon [name]="action.icon" [color]="action.color" />
              <span [class]="'text-' + action.color">{{ action.title }}</span>
            </button>
          }
        </mat-menu>
      }
    </div>
    <div>
      <sd-section title="Thông tin đơn hàng">
        @if (drawerMode() === 'detail') {
          <sd-section-item label="Khách hàng">{{ record().customer }}</sd-section-item>
          <sd-section-item label="Khu vực">{{ record().region }}</sd-section-item>
          <sd-section-item label="Giá trị đơn hàng">{{ (+record().amount).toLocaleString('vi-VN') }} ₫</sd-section-item>
        } @else {
          <div class="p-20 d-flex flex-column gap-8">
            <sd-input label="Khách hàng" [(model)]="draft.customer" [disabled]="pending()['drawer']" required />
            <sd-input label="Khu vực" [(model)]="draft.region" [disabled]="pending()['drawer']" required />
            <sd-input label="Giá trị đơn hàng (VND)" [(model)]="draft.amount" [disabled]="pending()['drawer']" required />
          </div>
        }
      </sd-section>
      <p role="status">{{ messages()['drawer'] }}</p>
    </div>
    <div sdFooterRight class="d-flex align-items-center flex-wrap gap-8 justify-content-end">
      <sd-button title="Đóng" type="text" [disabled]="pending()['drawer']" (click)="closeDrawer()" />
      @if (drawerMode() === 'detail' && !groupedDrawer()) {
        <sd-button
          title="Từ chối"
          prefixIcon="close"
          type="light"
          color="warning"
          [disabled]="pending()['drawer']"
          (click)="act('drawer', 'Từ chối')" />
      }
      @if (drawerMode() !== 'detail' || !groupedDrawer()) {
        <sd-button
          [title]="drawerMode() === 'detail' ? 'Duyệt' : 'Lưu'"
