      <sd-button title="Đóng" type="text" (click)="tableDrawer.requestClose()" />
      @if (tableMode() === 'selection') {
        <sd-button
          title="Xác nhận lựa chọn"
          prefixIcon="check"
          type="fill"
          color="primary"
          [disabled]="!picked().length"
