}
.pattern-layout > * {
  min-width: 0;
}
.variants {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--sd-border);
  border-radius: 8px;
  background: var(--sd-surface);
}
.variants a {
  padding: 12px;
  color: var(--sd-text);
  text-decoration: none;
  border: 0;
  border-radius: 4px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.variants a.active {
  color: var(--sd-primary);
  background: var(--sd-primary-light, #edf2ff);
  font-weight: 600;
}
.surface {
  border: 1px solid var(--sd-border);
  border-radius: 8px;
  background: var(--sd-surface);
  overflow: hidden;
  min-width: 0;
}
.preview-title,
.guide {
  padding: 18px 20px;
  border-bottom: 1px solid var(--sd-border);
}
.preview-title {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}
.preview-stage {
  padding: 20px;
  background: var(--sd-background, #f8f9fa);
  min-width: 0;
}
h2 {
  font-size: 18px;
  margin: 0;
}
h3 {
  font-size: 15px;
  margin: 0 0 12px;
}
p {
