    min-height: 0;
  }
  .surface {
    display: flex;
    flex-direction: column;
  }
  .preview-title {
    flex-shrink: 0;
  }
  sd-tab-group {
    flex: 1;
    min-height: 0;
  }
  .preview-stage {
    height: 100%;
    padding: 12px;
